entries[408272] = { ["name"] = "Vantus Rune: Aberrus, the Shadowed Crucible", ["text"] = "3.5 sec cast\nReagents:\nBurnished Ink (2), Chilled Rune\nOptional Reagents:\nBlotting Sand (#221) , Lesser Illustrious Insight (#92)\nVendor:\nScridorsa the Chiseler\nZone:\nZaralek Cavern\nCost:\n1\n\nUse: Attune yourself to the energies of the targeted Aberrus, the Shadowed Crucible raid boss, increasing your Versatility by 77 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\n70" }
